DROP TABLE IF EXISTS `bank_asia_ac_creations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bank_asia_ac_creations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint unsigned DEFAULT NULL,
  `date` date NOT NULL,
  `account_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_name_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_name_bn` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `father_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mother_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `spouse_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `gender` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nid_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nationality` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Bangladeshi',
  `religion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occupation` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `monthly_income` decimal(15,2) DEFAULT NULL,
  `source_of_funds` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `present_address` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `permanent_address` text COLLATE utf8mb4_unicode_ci,
  `mobile_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `account_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nominee_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nominee_relation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nominee_share_percent` int NOT NULL DEFAULT '100',
  `nominee_nid_dob` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_photo_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_nid_front_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_nid_back_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_signature_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nominee_photo_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `agent_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agent_designation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agent_mobile` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `outlet_name_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bank_asia_ac_creations_company_id_index` (`company_id`),
  KEY `bank_asia_ac_creations_status_index` (`status`),
  CONSTRAINT `bank_asia_ac_creations_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
