--
-- Table structure for table `computer_training_marketing_leads`
--

DROP TABLE IF EXISTS `computer_training_marketing_leads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `computer_training_marketing_leads` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint unsigned DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `school_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `interested_course` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `duration` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('new','contacting','interested','admitted','not interested') COLLATE utf8mb4_unicode_ci DEFAULT 'new',
  `call_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `next_follow_up_at` timestamp NULL DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `computer_training_marketing_leads_company_id_status_index` (`company_id`,`status`),
  KEY `computer_training_marketing_leads_name_index` (`name`),
  KEY `computer_training_marketing_leads_phone_index` (`phone`),
  KEY `computer_training_marketing_leads_interested_course_index` (`interested_course`),
  KEY `computer_training_marketing_leads_source_index` (`source`),
  KEY `computer_training_marketing_leads_status_index` (`status`),
  KEY `computer_training_marketing_leads_next_follow_up_at_index` (`next_follow_up_at`),
  KEY `computer_training_marketing_leads_school_name_index` (`school_name`),
  CONSTRAINT `computer_training_marketing_leads_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=706 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

