--
-- Table structure for table `computer_training_notices`
--

DROP TABLE IF EXISTS `computer_training_notices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `computer_training_notices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_course` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_batch_id` bigint unsigned DEFAULT NULL,
  `target_student_id` bigint unsigned DEFAULT NULL,
  `publish_date` date NOT NULL,
  `audience` enum('all','students','leads','staff') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `computer_training_notices_company_id_publish_date_index` (`company_id`,`publish_date`),
  KEY `computer_training_notices_publish_date_index` (`publish_date`),
  KEY `computer_training_notices_audience_index` (`audience`),
  KEY `computer_training_notices_is_active_index` (`is_active`),
  KEY `computer_training_notices_target_batch_id_foreign` (`target_batch_id`),
